  "claim": {
    "component_id": "C048",
    "value": "Evaluation of canary phase and tail changes should include whether unfinished exports increase.",
    "scope": "The proposed favorable outcome requires no increase in unfinished exports; no actual completion result is reported.",
    "provenance": {
