      ],
      "support_status": "SUFFICIENT",
      "rationale": "P022 explicitly includes unfinished exports in the canary evaluation. P021 identifies the observations as proposed rather than reported results."
    }
  },
  "signal_basis": {
    "component_id": "C048_SIGNAL_BASIS",
    "value": "Evaluate changes in the predicted phase and overall tail together with failures and unfinished exports, using predefined completion-rate bounds and accounting for incomplete exports missing from completed-export samples.",
    "scope": "The proposed canary evaluation; incomplete exports are accounted for where records permit, without asserting an observed completion outcome.",
    "provenance": {
      "refs": [
        {
          "source_id": "P022",
          "role": "SUPPORT"
